 function renderCharacters(body){const heading=document.createElement('div');heading.className='campaign-section-heading';heading.innerHTML='<div><h3>Characters & creatures</h3><p>Describe, explore concepts, generate a miniature and prepare a character sheet in one guided workspace.</p></div>';const create=document.createElement('button');create.className='primary';create.textContent='+ Create character';create.onclick=run(()=>openDesign('character'));const library=document.createElement('button');library.textContent='Browse character library';library.onclick=run(()=>designer.browse('character'));heading.append(create,library);body.append(heading);const grid=document.createElement('div');grid.className='campaign-character-grid';for(const character of campaign.characters){const card=document.createElement('article');card.className='campaign-character-card';if(character.portrait){const image=document.createElement('img');image.src=character.portrait;image.alt=character.name;image.className='campaign-character-image';card.append(image);}const copy=document.createElement('div');copy.className='campaign-character-copy';const name=document.createElement('h4'),details=document.createElement('p'),open=document.createElement('button');name.textContent=character.name;details.textContent='AC '+character.ac+' · HP '+character.hp+' · '+character.details;open.textContent='Open character workspace';open.onclick=run(async()=>{let id=character.libraryAssetId;if(!id){let a=await api.creativeCreate({kind:'character',name:character.name,packName:'My characters'});a.description=character.details;a.sheet={hitPoints:character.hp,armourClass:character.ac,equipment:character.equipment,spells:character.spells,biography:character.details};if(character.portrait){const conceptId=crypto.randomUUID();a.concepts=[{id:conceptId,name:'Imported campaign portrait',image:character.portrait,retained:true,approved:true,createdAt:Date.now()}];a.selectedConceptId=conceptId;}a=await api.creativeSave(a);character.libraryAssetId=a.id;await persist();id=a.id;}await openDesign('character',id);});copy.append(name,details,open);card.append(copy);grid.append(card);}if(!campaign.characters.length){const empty=document.createElement('p');empty.textContent='Create a character or add one from your reusable library.';grid.append(empty);}body.append(grid);}

 function renderStory(body){body.innerHTML='<h3>'+(campaign.gameType==='custom'?'Your game brief':'Your campaign brief')+'</h3><p id="campaign-brief-preview"></p><details id="campaign-manual-edit"><summary>Edit the brief and memory manually</summary><form id="campaign-brief-form"></form><label>'+(campaign.gameType==='custom'?'Agreed design decisions':'Lasting story decisions')+'<textarea id="campaign-summary" rows="4"></textarea></label><label>'+(campaign.gameType==='custom'?'Design progress / open questions':'Current session / unresolved threads')+'<textarea id="campaign-progress" rows="3"></textarea></label><button id="campaign-memory-save">'+(campaign.gameType==='custom'?'Save game memory':'Save campaign memory')+'</button><p>AI requests include only relevant excerpts from saved project information and recent messages. Earlier conversation stays saved locally.</p></details>';const preview=$('campaign-brief-preview');preview.textContent=(campaign.summary?(campaign.summary+' '+Object.values(campaign.setup).filter(Boolean).join(' · ')):'')||'Your companion will help build this brief. It is saved only after you review it.';const brief=$('campaign-brief-form');const nameLabel=document.createElement('label');nameLabel.textContent=campaign.gameType==='custom'?'Game name':'Campaign name';const nameInput=document.createElement('input');nameInput.id='campaign-manual-name';nameInput.value=campaign.name;nameInput.required=true;nameInput.maxLength=120;nameLabel.append(nameInput);brief.append(nameLabel);for(const [key,value]of Object.entries(campaign.setup)){const l=document.createElement('label');l.textContent=vocabulary().setupLabels[key];const input=document.createElement('input');input.name=key;input.value=value;input.maxLength=2000;l.append(input);brief.append(l);}const briefSave=document.createElement('button');briefSave.textContent=campaign.gameType==='custom'?'Save & approve game brief':'Save & approve campaign brief';brief.append(briefSave);brief.onsubmit=run(async()=>{campaign.name=nameInput.value.trim();campaign.summary=$('campaign-summary').value;campaign.progress=$('campaign-progress').value;campaign.assistant={phase:'studio',draftBrief:null,nextStep:campaign.gameType==='custom'?'Brief saved. Develop rules, player pieces or board layouts with your companion.':'Brief saved. Add an opening mission or character, manually or with your companion.'};for(const key of Object.keys(campaign.setup))campaign.setup[key]=brief.elements.namedItem(key).value;await persist();render();});$('campaign-summary').value=campaign.summary;$('campaign-progress').value=campaign.progress;$('campaign-memory-save').onclick=run(async()=>{campaign.summary=$('campaign-summary').value;campaign.progress=$('campaign-progress').value;await persist();render();});}
 function renderLinks(body){const actions=document.createElement('div');actions.className='campaign-link-actions';for(const [kind,label]of [['world','Add saved world'],['scene','Add encounter / scene']]){const add=document.createElement('button');add.textContent=label;add.onclick=run(async()=>{await persist();const c=await api.campaignLinkProject(campaign.id,kind);if(c)campaign=c;render();});actions.append(add);}body.append(actions);const notice=document.createElement('p');notice.textContent='Pickers open in your saved Worlds or Encounters folder in Documents · Terrain Foundry · Projects. Linked source files are tracked for review and are not silently changed.';body.append(notice);for(const link of campaign.links){const row=document.createElement('div');row.className='campaign-link';const text=document.createElement('span');text.textContent=link.name+' · '+link.kind;const open=document.createElement('button');open.textContent='Open in terrain editor';open.onclick=run(async()=>{const p=validateProject(await api.campaignLinkedProject(campaign.id,link.id));if(isDirty()&&!confirm('Save current scene first if needed. Open this linked project?'))return;replace(p);panel.close();});const state=document.createElement('span'),refresh=document.createElement('button'),locate=document.createElement('button');refresh.textContent='Accept source update';locate.textContent='Locate / relink source…';refresh.hidden=true;api.campaignReferenceStatus(campaign.id,link.id).then(v=>{state.textContent=v.legacy?'Legacy snapshot':v.missing?'Source missing · saved revision retained':v.changed?'Source updated · saved revision retained':'Shared reference up to date';refresh.hidden=!v.changed;}).catch(e=>{state.textContent=e.message;});const update=where=>run(async()=>{await persist();if(!confirm('Accept this source revision for this campaign? The previous revision remains in the shared cache.'))return;const c=await api.campaignReferenceRefresh(campaign.id,link.id,campaign.revision,where);if(c)campaign=c;render();});refresh.onclick=update(false);locate.onclick=update(true);const undo=document.createElement('button');undo.textContent='Undo last AI terrain edit';undo.onclick=run(async()=>{await persist();campaign=await api.campaignTerrainUndo(campaign.id,link.id,campaign.revision);render();});row.append(text,state,open,refresh,locate,undo);body.append(row);}}

 function renderGM(body){body.innerHTML='<form id="campaign-dice-form"><label>Dice<input id="campaign-dice" value="1d20" maxlength="20"></label><select id="campaign-dice-mode" aria-label="Roll mode"><option>Normal</option><option>Advantage</option><option>Disadvantage</option></select><button>Roll</button><output id="campaign-dice-result"></output></form><h3>Initiative</h3><form id="campaign-initiative-add"><input id="campaign-initiative-name" aria-label="Combatant name" placeholder="Character / monster" required maxlength="160"><input id="campaign-initiative-score" aria-label="Initiative score" type="number" value="0" min="-100" max="100"><input id="campaign-initiative-hp" aria-label="Hit points" type="number" value="0" min="0" max="100000"><button>Add</button></form><button id="campaign-initiative-sort">Sort initiative</button><button id="campaign-initiative-roll">Roll d20 initiatives</button><div id="campaign-initiative-list"></div>';if(!vocabulary().dnd){body.querySelector('h3').textContent='Turn order';const dice=$('campaign-dice');dice.value='';dice.placeholder='For example: 2d6';dice.parentElement.firstChild.textContent='Optional dice calculator';$('campaign-dice-mode').hidden=true;$('campaign-initiative-name').setAttribute('aria-label','Player or piece name');$('campaign-initiative-name').placeholder=campaign.gameType==='custom'?'Player / piece':'Unit / operative';$('campaign-initiative-score').setAttribute('aria-label','Turn order');$('campaign-initiative-hp').hidden=true;$('campaign-initiative-sort').textContent='Sort turn order';$('campaign-initiative-roll').hidden=true;} $('campaign-dice-form').onsubmit=run(async()=>{const notation=$('campaign-dice').value,mode=$('campaign-dice-mode').value,a=rollDice(notation),b=mode==='Normal'?null:rollDice(notation),result=JSON.stringify({mode,rolls:b?[a,b]:[a],total:b?(mode==='Advantage'?Math.max(a.total,b.total):Math.min(a.total,b.total)):a.total});campaign.diceLog=[...(campaign.diceLog||[]),{at:new Date().toISOString(),notation,result}].slice(-100);await persist();render();});const log=document.createElement('pre');log.textContent=(campaign.diceLog||[]).map(x=>x.notation+' '+x.result).join('\n');body.append(log);const next=document.createElement('button');next.textContent='Next turn · round '+(campaign.round||1)+' · '+(campaign.initiative[campaign.turn||0]?.name||(vocabulary().dnd?'No combatants':'No entries'));next.onclick=run(async()=>{if(!campaign.initiative.length)return;campaign.turn=(campaign.turn||0)+1;if(campaign.turn>=campaign.initiative.length){campaign.turn=0;campaign.round=(campaign.round||1)+1;}await persist();render();});body.append(next);$('campaign-initiative-add').onsubmit=run(async()=>{campaign.initiative.push({id:crypto.randomUUID(),name:$('campaign-initiative-name').value,score:Number($('campaign-initiative-score').value),hp:Number($('campaign-initiative-hp').value)});await persist();render();});$('campaign-initiative-sort').onclick=run(async()=>{campaign.initiative.sort((a,b)=>b.score-a.score);await persist();render();});$('campaign-initiative-roll').onclick=run(async()=>{campaign.initiative.forEach(x=>x.score=rollDice('1d20').total);campaign.initiative.sort((a,b)=>b.score-a.score);await persist();render();});for(const x of campaign.initiative){const row=document.createElement('p');row.textContent=x.score+' · '+x.name+(vocabulary().dnd?' · HP ':'');const hp=document.createElement('input');hp.type='number';hp.hidden=!vocabulary().dnd;hp.value=x.hp;hp.onchange=run(async()=>{x.hp=Number(hp.value);await persist();});row.append(hp);$('campaign-initiative-list').append(row);}editor(body,'widgets',[['title',vocabulary().dnd?'GM widget':'Play reference'],['body','Your rules / reminders','textarea']]);}
 async function playSound(sound){if(audios.has(sound.id)){const audio=audios.get(sound.id);if(!audio.paused){audio.pause();audio.currentTime=0;return;}await audio.play();return;}const data=await api.campaignSoundBytes(campaign.id,sound.id),url=URL.createObjectURL(new Blob([data.bytes],{type:data.mime})),audio=new Audio(url);audio.loop=sound.loop;audio.volume=sound.volume;audios.set(sound.id,audio);await audio.play();}
 function renderSounds(body){body.innerHTML='<p>Import sounds you own or are licensed to use. No third-party sound library is downloaded. In Stream Deck, configure a Hotkey action: Ctrl + Alt + Shift + F1–F12. Terrain Foundry must have focus. A native Stream Deck plug-in is not included.</p><label>Licence / source<input id="campaign-sound-license" maxlength="2000" placeholder="My recording, or licence and source"></label><button id="campaign-sound-starter">Add original synthesized starter sounds</button><button id="campaign-sound-import">Import local sound…</button><button id="campaign-sound-stop">Stop all sounds</button><div id="campaign-sound-grid" class="studio-choices"></div>';$('campaign-sound-starter').onclick=run(async()=>{await persist();campaign=await api.campaignStarterSounds(campaign.id);render();});$('campaign-sound-import').onclick=run(async()=>{await persist();const c=await api.campaignImportSound(campaign.id,$('campaign-sound-license').value);if(c)campaign=c;render();});$('campaign-sound-stop').onclick=()=>audios.forEach(a=>{a.pause();a.currentTime=0;});for(const sound of campaign.sounds){const row=document.createElement('div'),button=document.createElement('button');button.textContent='F'+sound.slot+' · '+sound.name;button.onclick=run(()=>playSound(sound));const loop=document.createElement('label');loop.innerHTML='<input type="checkbox"> Loop';loop.firstChild.checked=sound.loop;loop.firstChild.onchange=run(async()=>{sound.loop=loop.firstChild.checked;if(audios.has(sound.id))audios.get(sound.id).loop=sound.loop;await persist();});const volume=document.createElement('input');volume.type='range';volume.min=0;volume.max=1;volume.step=.05;volume.value=sound.volume;volume.setAttribute('aria-label',sound.name+' volume');volume.onchange=run(async()=>{sound.volume=+volume.value;if(audios.has(sound.id))audios.get(sound.id).volume=sound.volume;await persist();});row.append(button,loop,volume);$('campaign-sound-grid').append(row);}}
 document.addEventListener('keydown',e=>{if(!campaign||!e.ctrlKey||!e.altKey||!e.shiftKey||!/^F(?:[1-9]|1[0-2])$/.test(e.key))return;e.preventDefault();const sound=campaign.sounds.find(s=>s.slot===Number(e.key.slice(1)));if(sound)playSound(sound).catch(error=>toast(error.message,true));});
 function renderPlaybook(body){body.innerHTML='<h3>'+vocabulary().guide+'</h3><p>Follow your saved entries and layouts, with local audio cues. Printing produces static pages; this live playbook stays on your PC.</p><button id="campaign-run">'+vocabulary().guide+' · fullscreen</button><form id="campaign-cue-form"><label>Entry / linked scene<select id="campaign-cue-entry"></select></label><label>Sound cue<select id="campaign-cue-sound"></select></label><button>Add audio cue</button></form><div id="campaign-cue-list"></div>';const entries=[...campaign.items,...campaign.links];for(const x of entries)$('campaign-cue-entry').append(option(x.id,x.title||x.name));for(const x of campaign.sounds)$('campaign-cue-sound').append(option(x.id,x.name));$('campaign-cue-form').onsubmit=run(async()=>{const entryId=$('campaign-cue-entry').value,soundId=$('campaign-cue-sound').value;if(!entryId||!soundId)throw Error('Add an entry and a sound first');campaign.cues??=[];campaign.cues.push({id:crypto.randomUUID(),entryId,soundId});await persist();render();});for(const cue of campaign.cues||[]){const row=document.createElement('p');row.textContent=(entries.find(x=>x.id===cue.entryId)?.title||entries.find(x=>x.id===cue.entryId)?.name)+' · '+campaign.sounds.find(x=>x.id===cue.soundId)?.name;const remove=document.createElement('button');remove.textContent='Remove cue';remove.onclick=run(async()=>{campaign.cues=campaign.cues.filter(x=>x.id!==cue.id);await persist();render();});row.append(remove);$('campaign-cue-list').append(row);} $('campaign-run').onclick=()=>{if(!entries.length){toast('Add campaign entries or linked scenes first',true);return;}const viewer=document.createElement('dialog');viewer.className='campaign-run';viewer.innerHTML='<header><h2></h2><button id="run-fullscreen">Toggle fullscreen</button><button id="run-close">Exit playbook</button></header><div class="run-layout"><nav></nav><article><h3></h3><p></p><div class="run-cues"></div></article></div><footer><button id="run-prev">Previous</button><button id="run-next">Next</button><button id="run-stop">Stop all audio</button></footer>';document.body.append(viewer);let index=0;const show=()=>{const x=entries[index];viewer.querySelector('h2').textContent=campaign.name+' · '+(index+1)+' / '+entries.length;viewer.querySelector('h3').textContent=x.title||x.name;viewer.querySelector('article p').textContent=x.body||'Linked '+x.kind+' · open it in the terrain editor from Linked projects.';const pads=viewer.querySelector('.run-cues');pads.replaceChildren();for(const cue of (campaign.cues||[]).filter(c=>c.entryId===x.id)){const sound=campaign.sounds.find(s=>s.id===cue.soundId),b=document.createElement('button');b.textContent='Play / stop · '+(sound?.name||'Missing sound');b.disabled=!sound;b.onclick=run(()=>playSound(sound));pads.append(b);}if(campaign.links.some(l=>l.id===x.id)){const b=document.createElement('button');b.textContent='Open linked terrain';b.onclick=run(async()=>{if(isDirty()&&!confirm('Open linked terrain over current scene?'))return;replace(validateProject(await api.campaignLinkedProject(campaign.id,x.id)));viewer.close();panel.close();});pads.append(b);}};entries.forEach((x,i)=>{const b=document.createElement('button');b.textContent=x.title||x.name;b.onclick=()=>{index=i;show();};viewer.querySelector('nav').append(b);});const advance=n=>{index=(index+n+entries.length)%entries.length;show();};viewer.querySelector('#run-prev').onclick=()=>advance(-1);viewer.querySelector('#run-next').onclick=()=>advance(1);viewer.querySelector('#run-close').onclick=()=>viewer.close();viewer.querySelector('#run-stop').onclick=()=>audios.forEach(a=>{a.pause();a.currentTime=0;});viewer.querySelector('#run-fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else viewer.requestFullscreen().catch(()=>toast('Fullscreen unavailable',true));};viewer.onkeydown=e=>{if(e.key==='ArrowRight')advance(1);if(e.key==='ArrowLeft')advance(-1);};viewer.onclose=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});viewer.remove();};viewer.showModal();show();viewer.requestFullscreen().catch(()=>{});};}
 function renderPrint(body){body.innerHTML='<h3>'+vocabulary().book+'</h3><label>Audience<select id="campaign-print-audience"><option value="dm">'+vocabulary().privateBook+'</option><option value="player">Player handout · visible content only</option></select></label><label>Format<select id="campaign-print-format"><option value="rulebook">Rulebook PDF</option><option value="rulebook-html">Rulebook HTML</option><option value="book">'+(campaign.gameType==='custom'?'Game design book PDF':'Campaign book PDF')+'</option><option value="cards">'+(campaign.gameType==='custom'?'Game element cards PDF':'Campaign item cards PDF')+'</option><option value="player-json">Player handout JSON</option></select></label><label><input id="campaign-print-duplex" type="checkbox"> Include matching card backs for duplex</label><button id="campaign-print-save" class="primary">Save printable document…</button><button id="campaign-open-portal">Open online campaign portal</button><p>Export a player handout JSON, then upload it in the portal. Only approved player-visible content is exported; full campaigns, private sounds and terrain files remain local. Online invitations require the separately configured portal service.</p><button id="campaign-cover-import">Import shared cover artwork…</button><p>Print A4 at 100% scale. For card backs use duplex, flip on long edge; print a two-page test before a full set. Long card text is clipped to card size: use the book for complete descriptions. For books choose your printer’s long-edge duplex setting. Shared covers appear in player handouts. Player exports have no chat, private summary, revision history, keys, audio or project geometry. This is an offline export, not a live invitation/account system.</p>';$('campaign-print-save').onclick=run(async()=>{await persist();const result=await api.campaignExport(campaign.id,{audience:$('campaign-print-audience').value,format:$('campaign-print-format').value,duplex:$('campaign-print-duplex').checked});if(result)toast('Saved '+result);});$('campaign-open-portal').onclick=run(()=>api.campaignOpenPortal());$('campaign-cover-import').onclick=run(async()=>{const image=await api.campaignImportImage();if(image){campaign.cover=image;await persist();render();}});if(campaign.cover){const image=document.createElement('img');image.className='campaign-cover';image.src=campaign.cover;image.alt='Shared campaign cover';body.append(image);}}
